import {
  Group,
  Mesh,
  PlaneGeometry,
  Color,
  Texture,
  Vector2,
  MathUtils,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  texture,
  float,
  color,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string}} assets
 * @property {{cinematicPrimitives:Array<{name:string,params:any}>}} cinematicPrimitives
 * @property {{textContent:Array<{type:string,text:string}>}} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Texture} textureLoader
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 * @property {{createTextMesh:(text:string,style:any)=>THREE.Object3D}} fontAtlas
 */

/**
 * Create the 3‑D film‑strip carousel.
 */
export default function createNode(config, ctx) {
  const group = new Group();
  // apply placement
  if (config.position) group.position.set(...Object.values(config.position));
  if (config.rotation) group.rotation.set(...Object.values(config.rotation));
  if (config.scale) group.scale.set(...Object.values(config.scale));

  // -----------------------------------------------------------------
  // Text helpers
  // -----------------------------------------------------------------
  const createText = (text, style) => {
    // fontAtlas is expected to expose a method that returns a mesh/object
    // using the supplied style (family, size, weight, color, etc.).
    // We forward the style directly; the implementation of fontAtlas decides.
    return ctx.fontAtlas.createTextMesh(text, style);
  };

  // -----------------------------------------------------------------
  // Headline & Body
  // -----------------------------------------------------------------
  const headlineStyle = {
    family: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  };
  const bodyStyle = {
    family: 'JetBrains Mono',
    fontSize: 26,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: '#e8ecf2',
  };

  const headlineMesh = createText('The collection', headlineStyle);
  headlineMesh.position.set(-2.6, 1.5, 0);
  group.add(headlineMesh);

  const bodyMesh = createText('Five calibres. One discipline.', bodyStyle);
  bodyMesh.position.set(-2.6, -1.5, 0);
  group.add(bodyMesh);

  // -----------------------------------------------------------------
  // Film‑strip (cards)
  // -----------------------------------------------------------------
  const strip = new Group();
  strip.rotation.y = MathUtils.degToRad(-18);
  group.add(strip);

  const baseImageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';
  const captions = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  const CARD_WIDTH = 1.6;
  const CARD_HEIGHT = 1.0;
  const BEVEL = 0.025;
  const PITCH = 1.85;
  const FOCUS_INDEX = 2; // middle card

  /** @type {Array<THREE.Material|THREE.Texture>} */
  const disposables = [];

  for (let i = 0; i < 5; i++) {
    const cardGroup = new Group();

    const xPos = (i - 2) * PITCH;
    cardGroup.position.set(xPos, 0, 0);
    strip.add(cardGroup);

    // -------------------------------------------------------------
    // Texture (distinct variant per card)
    // -------------------------------------------------------------
    const variantUrl = `${baseImageUrl}?v=${i}`;
    const tex = ctx.textureLoader(variantUrl);
    disposables.push(tex);

    // -------------------------------------------------------------
    // Material (Standard with map)
    // -------------------------------------------------------------
    const mapNode = texture(tex);
    const standardMat = new MeshStandardNodeMaterial();
    standardMat.mapNode = mapNode;
    standardMat.roughnessNode = float(0.55);
    standardMat.metalnessNode = float(0.2);
    standardMat.clearcoatNode = float(0.15);
    standardMat.transparent = true;

    const distanceFromCenter = Math.abs(i - FOCUS_INDEX);
    const opacityVal = 1 - distanceFromCenter * 0.225; // 1 → 0.55
    standardMat.opacityNode = float(opacityVal);
    disposables.push(standardMat);

    // -------------------------------------------------------------
    // Card geometry
    // -------------------------------------------------------------
    const cardGeom = new PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
    const cardMesh = new Mesh(cardGeom, standardMat);
    cardMesh.castShadow = true;
    cardMesh.receiveShadow = true;
    if (i !== FOCUS_INDEX) {
      const scaleFactor = 0.92;
      cardMesh.scale.setScalar(scaleFactor);
    }
    cardGroup.add(cardMesh);

    // -------------------------------------------------------------
    // Ink bevel frame
    // -------------------------------------------------------------
    const frameGeom = new PlaneGeometry(CARD_WIDTH + BEVEL * 2, CARD_HEIGHT + BEVEL * 2);
    const frameMat = new MeshBasicNodeMaterial();
    frameMat.colorNode = color(new Color('#16161d'));
    frameMat.depthWrite = false;
    frameMat.transparent = true;
    frameMat.opacityNode = float(1);
    disposables.push(frameMat);
    const frameMesh = new Mesh(frameGeom, frameMat);
    frameMesh.position.set(0, 0, -0.001); // slightly behind the image
    cardGroup.add(frameMesh);

    // -------------------------------------------------------------
    // Focused‑card underline (only for the central card)
    // -------------------------------------------------------------
    if (i === FOCUS_INDEX) {
      const underlineGeom = new PlaneGeometry(CARD_WIDTH, 0.035);
      const underlineMat = new MeshStandardNodeMaterial();
      underlineMat.emissiveNode = color(new Color('#ff2a38'));
      underlineMat.emissiveIntensityNode = float(1.3);
      underlineMat.roughnessNode = float(0.5);
      underlineMat.metalnessNode = float(0);
      disposables.push(underlineMat);
      const underlineMesh = new Mesh(underlineGeom, underlineMat);
      underlineMesh.position.set(0, -CARD_HEIGHT / 2 - 0.0175, 0.001);
      cardGroup.add(underlineMesh);
    }

    // -------------------------------------------------------------
    // Counter‑rotate focused card to face camera
    // -------------------------------------------------------------
    if (i === FOCUS_INDEX) {
      cardGroup.rotation.y = MathUtils.degToRad(18); // cancel strip tilt
    }

    // -------------------------------------------------------------
    // Caption text below each card
    // -------------------------------------------------------------
    const captionStyle = {
      family: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 700,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: '#e8ecf2',
    };
    const captionMesh = createText(captions[i], captionStyle);
    // Position: just under the card (taking into account possible scaling)
    const capY = -CARD_HEIGHT / 2 - 0.07;
    captionMesh.position.set(0, capY, 0.001);
    captionMesh.rotation.y = 0; // aligns with cardGroup rotation automatically
    cardGroup.add(captionMesh);
    // note: caption meshes are managed by fontAtlas; they will be disposed via its cleanup if needed
  }

  // -----------------------------------------------------------------
  // Apply cinematic primitives (e.g., parallax‑scroll)
  // -----------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        ctx.primitives[prim.name](group, prim.params);
      }
    }
  }

  // -----------------------------------------------------------------
  // UserData – handlers placeholder
  // -----------------------------------------------------------------
  group.userData.handlers = {};

  // -----------------------------------------------------------------
  // Cleanup
  // -----------------------------------------------------------------
  const timelines = []; // store any GSAP timelines we might create in the future

  group.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const d of disposables) {
      if (d instanceof Texture) {
        d.dispose();
      } else if (d.dispose) {
        d.dispose();
      }
    }
    // dispose of fontAtlas generated meshes if it provides a dispose method
    if (ctx.fontAtlas && typeof ctx.fontAtlas.dispose === 'function') {
      ctx.fontAtlas.dispose();
    }
  };

  return group;
}
